import{_ as t,o,c as a,ag as s}from"./chunks/framework.Cyu1VozZ.js";const u=JSON.parse('{"title":"Design Editor","description":"","frontmatter":{},"headers":[],"relativePath":"developers/design-editor.md","filePath":"developers/design-editor.md"}'),i={name:"developers/design-editor.md"};function n(r,e,h,d,l,c){return o(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="design-editor" tabindex="-1">Design Editor <a class="header-anchor" href="#design-editor" aria-label="Permalink to &quot;Design Editor&quot;">​</a></h1><p>Change how Wafflebase looks — colours, spacing, a button&#39;s hover state — by clicking on it, and turn what you changed into a pull request. The editor renders the <strong>real</strong> application against real component source, so what you see is what the committed code does.</p><p>You do not have to be able to write code to use it. You do need Node and a copy of the repository; everything after that is two commands.</p><div class="tip custom-block"><p class="custom-block-title">Nothing leaves your machine until you say so</p><p>The editor runs entirely on your computer. It has no backend, no database, and no network access — the pages it renders answer their own data requests from fixtures. Nothing is sent anywhere until you open a pull request, and that uses the GitHub credentials already on your machine.</p></div><h2 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h2><table tabindex="0"><thead><tr><th>You need</th><th>How to check</th><th>If you do not have it</th></tr></thead><tbody><tr><td><strong>Node 22 or newer</strong></td><td><code>node --version</code></td><td>Install the LTS build from <a href="https://nodejs.org" target="_blank" rel="noreferrer">nodejs.org</a></td></tr><tr><td><strong>Git</strong></td><td><code>git --version</code></td><td>Install from <a href="https://git-scm.com" target="_blank" rel="noreferrer">git-scm.com</a></td></tr><tr><td><strong>A name AND an address on your commits</strong></td><td><code>git config --get user.name &amp;&amp; git config --get user.email</code> — it must print two lines</td><td><code>git config --global user.name &quot;Your Name&quot;</code> and <code>git config --global user.email &quot;you@example.com&quot;</code>. Git needs <strong>both</strong>; one without the other still cannot commit.</td></tr><tr><td>A copy of the repository</td><td>—</td><td><code>git clone https://github.com/wafflebase/wafflebase.git</code></td></tr></tbody></table><p>Nothing else. You do <strong>not</strong> need pnpm, Docker, a database, or the GitHub CLI — the steps below either prepare them or work without them.</p><h2 id="step-1-—-open-the-editor" tabindex="-1">Step 1 — Open the editor <a class="header-anchor" href="#step-1-—-open-the-editor" aria-label="Permalink to &quot;Step 1 — Open the editor&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wafflebase</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> design</span></span></code></pre></div><p>If you do not have pnpm yet, run <code>node scripts/design.mjs</code> instead. It is the same thing, and it prepares pnpm for you.</p><p>The first run installs dependencies. Measured on a clone with nothing installed: <strong>about two minutes</strong> to a working editor — longer on a slow connection, and seconds on every run after that. It prints what it is doing and then opens your browser:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>✓ dependencies installed</span></span>
<span class="line"><span>✓ editor built</span></span>
<span class="line"><span>✓ @wafflebase/core built</span></span>
<span class="line"><span>✓ the design editor is at http://localhost:5173/__design-editor/</span></span></code></pre></div><p>Every later run skips whatever is already done and goes straight to the editor. If the browser does not open by itself, click the printed address.</p><details class="details custom-block"><summary>The port may not be 5173</summary><p>If something else is already using it, Vite takes the next free port and the command prints the real one. Always use the address it printed.</p></details><h2 id="step-2-—-change-something" tabindex="-1">Step 2 — Change something <a class="header-anchor" href="#step-2-—-change-something" aria-label="Permalink to &quot;Step 2 — Change something&quot;">​</a></h2><p>The editor has three panes.</p><p><strong>Left — what you are looking at.</strong> Two modes:</p><ul><li><strong>Components</strong> — one piece of the design system on its own: a button, a card, a menu. Grouped into <em>Primitives</em> (things that stand alone) and <em>App components</em> (things that need data, which the editor invents for them).</li><li><strong>Scenes</strong> — a whole page of the real app: the documents list, the login screen, the settings page.</li></ul><p><strong>Centre — the thing itself.</strong> Drag the empty background to move it, <code>Ctrl</code>/<code>⌘</code> and scroll to zoom around the pointer. The buttons above it switch a component&#39;s variant and interaction state, so you can sit and look at a hover style without holding the mouse still.</p><p><strong>Right — what you can change.</strong></p><ul><li><strong>Layout</strong> shows the structure of what is on screen. Click a row to select that piece; a small editor appears beside it for spacing, size and alignment.</li><li><strong>Bindings</strong> is where colours live. Every colour is a <em>token</em> — a name like <code>primary</code> — and this pane says which token each part uses. Change the token, or change what the token itself resolves to, and everything using it follows.</li></ul><p>Every change previews immediately. Nothing is written to any file yet.</p><h2 id="step-3-—-save-to-code" tabindex="-1">Step 3 — Save to code <a class="header-anchor" href="#step-3-—-save-to-code" aria-label="Permalink to &quot;Step 3 — Save to code&quot;">​</a></h2><p>The <strong>Save to Code</strong> button in the header shows how many changes are staged. Pressing it opens a review with the component <strong>as it is now beside how it will be</strong>, and under that the exact lines that will change in each file.</p><p>Nothing is written until you approve it. Once you do, the changes are in the repository&#39;s files on your computer — and still nowhere else. See <a href="#where-the-changes-went">Where the changes went</a> if you want to look at them.</p><div class="warning custom-block"><p class="custom-block-title">Leave the editor running</p><p>The next step reads the editor&#39;s record of what you changed, which lives in the running server. If you close it, the pull request is still possible but its description will be less precise. See <a href="#if-the-editor-is-closed">If the editor is closed</a>.</p></div><h2 id="where-the-changes-went" tabindex="-1">Where the changes went <a class="header-anchor" href="#where-the-changes-went" aria-label="Permalink to &quot;Where the changes went&quot;">​</a></h2><p>Two places answer this, and both are in the editor&#39;s header.</p><p><strong>The write log</strong> (the scroll icon, with a count beside it) lists everything written this session, newest first — what each change was, and <strong>which files it landed in</strong>. That is the durable record; the toast that appears at save time says the same thing and then disappears.</p><p><strong>The ⓘ button</strong> reports <code>Editing</code>, which is the folder the editor writes to. If you have more than one copy of the repository — a second clone, or a git worktree — this is the one that matters. Looking at <code>git diff</code> in a <em>different</em> copy shows nothing, and nothing is wrong.</p><p>From a terminal in that folder, <code>git diff</code> shows the change itself. A colour usually lands in <code>packages/core/src/tokens/</code> (that is where the design tokens live); a change scoped to one component lands in that component&#39;s own file.</p><h2 id="step-4-—-open-a-pull-request" tabindex="-1">Step 4 — Open a pull request <a class="header-anchor" href="#step-4-—-open-a-pull-request" aria-label="Permalink to &quot;Step 4 — Open a pull request&quot;">​</a></h2><p>In a second terminal, in the same folder:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> design-pr</span></span></code></pre></div><p>It prints what it is about to do — the branch it will create, the files it will commit, the title — and then does it. Add <code>--dry-run</code> to see that plan without changing anything.</p><p><strong>It commits only the files the editor changed.</strong> If you had other work in progress, it is listed and left alone.</p><p>What happens next depends on what you have installed. You do not have to know which case you are in; the command works it out and says so.</p><h3 id="if-you-have-the-github-cli-and-write-access" tabindex="-1">If you have the GitHub CLI and write access <a class="header-anchor" href="#if-you-have-the-github-cli-and-write-access" aria-label="Permalink to &quot;If you have the GitHub CLI and write access&quot;">​</a></h3><p>The branch is pushed and the pull request is opened. The command prints its address and opens it in your browser. Done.</p><h3 id="if-you-have-the-github-cli-but-no-write-access" tabindex="-1">If you have the GitHub CLI but no write access <a class="header-anchor" href="#if-you-have-the-github-cli-but-no-write-access" aria-label="Permalink to &quot;If you have the GitHub CLI but no write access&quot;">​</a></h3><p>Most people are here — you can read a repository you do not own. The command creates your own copy (a <em>fork</em>), pushes there, and opens the pull request against the original. You are asked to confirm the fork the first time.</p><h3 id="if-you-do-not-have-the-github-cli" tabindex="-1">If you do not have the GitHub CLI <a class="header-anchor" href="#if-you-do-not-have-the-github-cli" aria-label="Permalink to &quot;If you do not have the GitHub CLI&quot;">​</a></h3><p>You still get a pull request. The command pushes your branch and opens GitHub&#39;s &quot;compare&quot; page in your browser, which is a form with everything already filled in — press the green button to create it.</p><p>This is the path that needs nothing but a browser. If you would rather have the first case, install the <a href="https://cli.github.com" target="_blank" rel="noreferrer">GitHub CLI</a> and run <code>gh auth login</code> once.</p><h3 id="if-you-have-no-origin-to-push-to" tabindex="-1">If you have no <code>origin</code> to push to <a class="header-anchor" href="#if-you-have-no-origin-to-push-to" aria-label="Permalink to &quot;If you have no \`origin\` to push to&quot;">​</a></h3><p>The command stops and tells you. This happens when the repository was copied rather than cloned. Clone it instead:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/wafflebase/wafflebase.git</span></span></code></pre></div><h2 id="writing-a-better-description" tabindex="-1">Writing a better description <a class="header-anchor" href="#writing-a-better-description" aria-label="Permalink to &quot;Writing a better description&quot;">​</a></h2><p>The generated description lists what changed, taken from the editor&#39;s own record of your edits — accurate, and a little dry.</p><p>If you have <a href="https://claude.com/claude-code" target="_blank" rel="noreferrer">Claude Code</a> installed, ask it to open the pull request instead:</p><blockquote><p>Open a PR for my design changes</p></blockquote><p>It reads the same record, looks at the resulting diff, and writes a title and description a reviewer can act on — then hands them to the same command. You can also pass your own:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> design-pr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --title</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Soften the primary button&#39;s hover&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --body-file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> notes.md</span></span></code></pre></div><h2 id="if-the-editor-is-closed" tabindex="-1">If the editor is closed <a class="header-anchor" href="#if-the-editor-is-closed" aria-label="Permalink to &quot;If the editor is closed&quot;">​</a></h2><p>The editor keeps its record of your edits in memory, so closing it loses the list of <em>which</em> edits you made — the changed files themselves are safe on disk.</p><p><code>pnpm design-pr</code> still works. It falls back to looking at every changed file in the folder and says so in its output and in the pull request, so nobody mistakes the wider list for the editor&#39;s own record. If that matters, reopen the editor before you save.</p><h2 id="what-it-will-never-do" tabindex="-1">What it will never do <a class="header-anchor" href="#what-it-will-never-do" aria-label="Permalink to &quot;What it will never do&quot;">​</a></h2><p>These are guarantees, not conventions:</p><ul><li>It never commits on <code>main</code> — it always creates a branch.</li><li>It never commits a file the editor did not change.</li><li>It never force-pushes and never overwrites an existing branch.</li><li>It never stores or asks for a password or a token. <code>git</code> and <code>gh</code> run as you, with the credentials already on your machine.</li></ul><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>What you see</th><th>What it means</th></tr></thead><tbody><tr><td><code>Node 22 or newer is required</code></td><td>Install the LTS build from <a href="https://nodejs.org" target="_blank" rel="noreferrer">nodejs.org</a> and run the command again.</td></tr><tr><td><code>Nothing has changed</code></td><td>The editor has written nothing yet. Make a change, press <strong>Save to Code</strong>, approve it, then try again.</td></tr><tr><td>Every scene says <strong>mount error</strong></td><td>Something the scenes need was not built. <code>pnpm design</code> builds it for you — if you started the server another way, run <code>pnpm design</code> instead.</td></tr><tr><td>The page is blank, or a component says it needs app context</td><td>Some pieces of a design system cannot be shown on their own — a menu item needs its menu. Open the whole component instead of its part.</td></tr><tr><td>A change previews but the page looks unchanged</td><td>The editor is showing a different scene from the one you are thinking of. Check the name above the centre pane.</td></tr><tr><td><code>git does not know who you are yet</code></td><td>Git is missing <code>user.name</code>, <code>user.email</code>, or both — the message names which. Run the <code>git config --global</code> commands it prints for the ones it names, then try again. Nothing was changed.</td></tr><tr><td><code>The push was refused</code></td><td>You do not have write access and the GitHub CLI is not available to make you a fork. Install the <a href="https://cli.github.com" target="_blank" rel="noreferrer">GitHub CLI</a>, or fork the repository on GitHub first and clone your fork.</td></tr><tr><td>You saved, but <code>git diff</code> shows nothing</td><td>You are almost certainly looking at a different copy of the repository. Press ⓘ in the editor&#39;s header and read <code>Editing</code> — that is the folder it writes to.</td></tr></tbody></table><h2 id="using-it-on-your-own-project" tabindex="-1">Using it on your own project <a class="header-anchor" href="#using-it-on-your-own-project" aria-label="Permalink to &quot;Using it on your own project&quot;">​</a></h2><p>The editor is a Vite plugin, <code>@wafflebase/design-editor</code>, and the setup in this repository is one example of a consumer. Standing it up on another project is a developer task — see <a href="https://github.com/wafflebase/wafflebase/blob/main/.claude/skills/design-sandbox-bringup/SKILL.md" target="_blank" rel="noreferrer"><code>design-sandbox-bringup</code></a> for what it takes.</p><p>It has been installed into a project outside this repository and run there, so the claim is measured rather than intended. What that took, and the three defects it found, are in <a href="https://github.com/wafflebase/wafflebase/blob/main/docs/design/design-editor/design-editor-packaging.md" target="_blank" rel="noreferrer"><code>design-editor-packaging.md</code></a>. The package is <strong>not published to npm</strong> — a consumer installs it from a tarball (<code>npm pack</code>) or a workspace.</p>`,64)])])}const g=t(i,[["render",n]]);export{u as __pageData,g as default};
